import{_ as t,o as n,c as a,ag as i}from"./chunks/framework.DTisvaUJ.js";const h=JSON.parse('{"title":"Supporter edition (licenses)","description":"Mutelink is free. Learn about optional BOOTH extensions, license types, extra features and how to import a license.","frontmatter":{"description":"Mutelink is free. Learn about optional BOOTH extensions, license types, extra features and how to import a license.","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/en/about/supporter"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"property":"og:title","content":"Supporter edition (licenses) | Mutelink"}],["meta",{"property":"og:description","content":"Mutelink is free. Learn about optional BOOTH extensions, license types, extra features and how to import a license."}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/en/about/supporter"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"property":"og:image:width","content":"1920"}],["meta",{"property":"og:image:height","content":"1080"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Supporter edition (licenses) | Mutelink"}],["meta",{"name":"twitter:description","content":"Mutelink is free. Learn about optional BOOTH extensions, license types, extra features and how to import a license."}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/about/supporter"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/about/supporter"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/about/supporter"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/about/supporter"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/about/supporter"}]]},"headers":[],"relativePath":"en/about/supporter.md","filePath":"en/about/supporter.md"}'),o={name:"en/about/supporter.md"};function r(s,e,l,u,p,c){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="支援版-ライセンス" tabindex="-1">Supporter edition (licenses) <a class="header-anchor" href="#支援版-ライセンス" aria-label="Permalink to &quot;Supporter edition (licenses) {#支援版-ライセンス}&quot;">​</a></h1><p>The app is free. Supporter extensions are optional paid features; you can use the app without purchasing them.</p><h2 id="種類" tabindex="-1">Options <a class="header-anchor" href="#種類" aria-label="Permalink to &quot;Options {#種類}&quot;">​</a></h2><p>Available on the <a href="https://utyujin.booth.pm/items/8914909" target="_blank" rel="noreferrer">BOOTH product page</a>.</p><table tabindex="0"><thead><tr><th>Name</th><th>Price</th><th>Features</th></tr></thead><tbody><tr><td>Customization extension</td><td>¥500</td><td>Custom VR keyboard backgrounds and chatbox layouts; attach VR and control panels to your hands; make the main window background transparent to place over VRChat</td></tr><tr><td>AI voice extension</td><td>¥1,000</td><td>Voice cloning with Irodori-TTS and Qwen3-TTS; emoji, style and voice per suffix; reading translated text, including with VOICEVOX</td></tr><tr><td>Bundle</td><td>¥1,200</td><td>Both extensions above</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Names have changed</p><p>From v2.0.0, “VR background/chatbox extension” became “Customization extension,” and “IrodoriTTS extension” became “AI voice extension” as features expanded. Existing license files continue to work.</p></div><h2 id="無料で使えるもの" tabindex="-1">Free features <a class="header-anchor" href="#無料で使えるもの" aria-label="Permalink to &quot;Free features {#無料で使えるもの}&quot;">​</a></h2><p>The following do not require a purchase.</p><ul><li>Recognition, physical/VR keyboard input and chatbox messages</li><li>Speech with VOICEVOX and standard Irodori-TTS/Qwen3-TTS voices</li><li>Translation and sending translated text to the chatbox</li><li>Incoming speech recognition, translation and display</li><li>VR panels fixed in your view</li><li>Passing through your own microphone voice</li></ul><div class="tip custom-block"><p class="custom-block-title">Before purchasing</p><p>Installing Irodori-TTS/Qwen3-TTS and using their standard voices is free. Confirm they run on your PC before buying. Listen on the <a href="/Mutelink-releases/en/compare/voices">voice comparison page</a>.</p><p>For conversational Qwen3-TTS cloning, prepare the cloning model, an NVIDIA GPU and acceleration components. Without acceleration, measurements show generation can lag behind playback, so check speed with standard voices first.</p></div><h2 id="使いかた" tabindex="-1">How to use a license <a class="header-anchor" href="#使いかた" aria-label="Permalink to &quot;How to use a license {#使いかた}&quot;">​</a></h2><ol><li>After purchasing on BOOTH, download the license file.</li><li>Import it in Mutelink Settings &gt; Other &gt; License.</li><li>The corresponding features unlock and become available.</li></ol><p>Check active licenses on the same page.</p><h2 id="利用上の決まり" tabindex="-1">Usage rules <a class="header-anchor" href="#利用上の決まり" aria-label="Permalink to &quot;Usage rules {#利用上の決まり}&quot;">​</a></h2><ul><li>License files may only be used by the purchaser on their own PCs.</li><li>Redistribution, resale, transfer and sharing with others are prohibited.</li><li>Modifying license files or unlawfully enabling paid features is prohibited.</li><li>Register only your own voice or a voice whose owner has explicitly consented. Registering actors, celebrities or acquaintances without consent, impersonation and deceptive synthetic audio (including deepfakes) are prohibited.</li><li>Audio is not watermarked. You are responsible for how you use generated speech.</li><li>Do not violate applicable laws or VRChat rules.</li></ul><p>See the BOOTH product page for refunds, support, updates and disclaimers.</p>',16)])])}const m=t(o,[["render",r]]);export{h as __pageData,m as default};
